import os
import re
import json
import html
import urllib.request
from html.parser import HTMLParser

ESSAYS = [
    ("Do Things That Don't Scale", "https://www.paulgraham.com/ds.html"),
    ("Founder Mode", "https://www.paulgraham.com/foundermode.html"),
]

OUTPUT_DIR = "/root/tts_work"
AUDIO_OUTPUT = "/root/audiobook.mp3"
MODEL = "gpt-4o-mini-tts"
VOICE = "alloy"
MAX_CHARS = 3000  # conservative chunk size to stay under token limits

class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self._ignore = 0
        self._ignore_tags = {"script", "style", "noscript"}
        self._break_tags = {"br", "p", "hr", "h1", "h2", "h3", "h4", "h5", "h6", "li", "blockquote"}

    def handle_starttag(self, tag, attrs):
        if tag in self._ignore_tags:
            self._ignore += 1
        if tag in self._break_tags:
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in self._ignore_tags:
            self._ignore = max(0, self._ignore - 1)
        if tag in self._break_tags:
            self.parts.append("\n")

    def handle_data(self, data):
        if self._ignore:
            return
        self.parts.append(data)


def fetch_text(url: str) -> str:
    with urllib.request.urlopen(url) as resp:
        raw_html = resp.read().decode("utf-8", errors="replace")

    parser = TextExtractor()
    parser.feed(raw_html)
    text = html.unescape("".join(parser.parts))

    # Normalize whitespace
    text = text.replace("\r", "\n")
    text = re.sub(r"[ \t]+", " ", text)

    lines = [ln.strip() for ln in text.split("\n")]

    # Filter out navigation and boilerplate lines
    skip_phrases = [
        "Back to Paul Graham",
        "Translations",
        "Want to start a startup?",
        "View all essays",
    ]

    cleaned = []
    for ln in lines:
        if not ln:
            if cleaned and cleaned[-1] != "":
                cleaned.append("")
            continue
        if any(ln.startswith(p) for p in skip_phrases):
            continue
        if ln == "Image":
            continue
        cleaned.append(ln)

    # Collapse multiple blank lines
    out = []
    for ln in cleaned:
        if ln == "" and (not out or out[-1] == ""):
            continue
        out.append(ln)

    return "\n".join(out).strip()


def chunk_text(text: str, max_chars: int):
    paras = [p.strip() for p in text.split("\n\n") if p.strip()]
    chunks = []
    buf = ""
    for p in paras:
        addition = (p + "\n\n")
        if len(buf) + len(addition) > max_chars and buf:
            chunks.append(buf.strip())
            buf = ""
        buf += addition
    if buf.strip():
        chunks.append(buf.strip())
    return chunks


def tts_chunk(text: str, out_path: str, api_key: str):
    payload = {
        "model": MODEL,
        "voice": VOICE,
        "input": text,
        "response_format": "mp3",
    }
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        "https://api.openai.com/v1/audio/speech",
        data=data,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
    )
    with urllib.request.urlopen(req) as resp:
        audio = resp.read()
    with open(out_path, "wb") as f:
        f.write(audio)


def main():
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise SystemExit("OPENAI_API_KEY not set in environment")

    all_text = []
    for title, url in ESSAYS:
        essay_text = fetch_text(url)
        header = f"Essay: {title}\n\n"
        footer = "\n\nEnd of essay.\n\n"
        all_text.append(header + essay_text + footer)

    full_text = "".join(all_text).strip()

    chunks = chunk_text(full_text, MAX_CHARS)

    segment_paths = []
    for i, chunk in enumerate(chunks, start=1):
        out_path = os.path.join(OUTPUT_DIR, f"segment_{i:03d}.mp3")
        tts_chunk(chunk, out_path, api_key)
        segment_paths.append(out_path)

    # Write concat list for ffmpeg
    list_path = os.path.join(OUTPUT_DIR, "segments.txt")
    with open(list_path, "w", encoding="utf-8") as f:
        for p in segment_paths:
            f.write(f"file '{p}'\n")

    # Concatenate without re-encoding
    os.system(
        f"ffmpeg -y -f concat -safe 0 -i {list_path} -c copy {AUDIO_OUTPUT}"
    )

    print(f"Wrote audiobook to {AUDIO_OUTPUT}")


if __name__ == "__main__":
    main()
